(function () {
var questoes = [
{"id": "AU-01ff08b018", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na pedagogia tradicional, segundo a classificação de José Carlos Libâneo,", "gabarito": "E", "comentario": "Libâneo classifica a pedagogia tradicional entre as tendências liberais. A avaliação costuma medir a reprodução do conteúdo.", "alternativas": [["A", "o estudante escolhe livremente o que quer aprender, conforme seus interesses."], ["B", "os conteúdos são definidos a partir dos temas geradores da comunidade."], ["C", "o professor atua apenas como facilitador das relações interpessoais."], ["D", "a escola se organiza em autogestão, sem autoridade do professor."], ["E", "o professor é o centro do processo, transmite os conteúdos como verdades prontas, e a aprendizagem se apoia na memorização e na repetição."]]},
{"id": "AU-4d576c4ca9", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A tendência renovada progressivista (Escola Nova), inspirada em John Dewey, caracteriza-se por", "gabarito": "C", "comentario": "A Escola Nova colocou o estudante no centro do processo. No Brasil, o Manifesto dos Pioneiros da Educação Nova (1932) foi um marco do movimento.", "alternativas": [["A", "defender a transmissão neutra de conteúdos, sem relação com a vida do estudante."], ["B", "priorizar a disciplina rígida e os castigos como forma de ensinar."], ["C", "valorizar a atividade do estudante, a experiência e o \"aprender fazendo\", com o professor como orientador."], ["D", "centrar o ensino na exposição oral e na memorização."], ["E", "organizar o ensino a partir de objetivos operacionais e instrução programada."]]},
{"id": "AU-92e159e865", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na tendência renovada não diretiva, associada a Carl Rogers,", "gabarito": "D", "comentario": "A preocupação maior é com o clima de confiança e com a autonomia do estudante; o conteúdo fica em segundo plano.", "alternativas": [["A", "a escola tem como função principal transmitir o saber sistematizado às camadas populares."], ["B", "o conteúdo é organizado em módulos de instrução programada."], ["C", "a avaliação é feita exclusivamente por provas objetivas."], ["D", "o professor atua como facilitador, e a ênfase está no desenvolvimento pessoal, na autorrealização e nas relações interpessoais."], ["E", "o professor controla todo o comportamento do estudante por meio de reforços."]]},
{"id": "AU-67269c18c8", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A tendência tecnicista, que marcou a educação brasileira nas décadas de 1960 e 1970, caracteriza-se por", "gabarito": "B", "comentario": "Inspirada na psicologia comportamental de Skinner, valoriza a instrução programada e o controle dos resultados.", "alternativas": [["A", "organizar a escola em autogestão pelos estudantes."], ["B", "organizar o ensino de forma racional e eficiente, com objetivos operacionais, técnicas e materiais instrucionais, em que professor e estudante executam um processo planejado por especialistas."], ["C", "partir dos temas geradores e do diálogo com a comunidade."], ["D", "colocar a afetividade e as relações interpessoais no centro do processo."], ["E", "recusar qualquer planejamento prévio das aulas."]]},
{"id": "AU-fa595a26db", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na pedagogia libertadora, de Paulo Freire,", "gabarito": "B", "comentario": "Freire criticava a \"educação bancária\" e propunha a educação problematizadora, com educador e educando aprendendo juntos.", "alternativas": [["A", "os conteúdos clássicos são transmitidos sem relação com a vida dos estudantes."], ["B", "os conteúdos partem de temas geradores extraídos da realidade dos educandos, problematizados no diálogo, com vistas à conscientização e à transformação social."], ["C", "o professor deposita os conhecimentos nos estudantes, que os recebem passivamente."], ["D", "a escola deve ser neutra diante das questões sociais."], ["E", "o ensino se baseia em objetivos comportamentais medidos por testes."]]},
{"id": "AU-4705e0dbaa", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para Paulo Freire, a chamada \"educação bancária\" é aquela em que", "gabarito": "E", "comentario": "Freire opunha a educação bancária à educação problematizadora e libertadora.", "alternativas": [["A", "o estudante aprende a administrar as finanças da família."], ["B", "educador e educando dialogam e constroem juntos o conhecimento."], ["C", "os conteúdos partem dos problemas vividos pela comunidade."], ["D", "a escola se organiza em cooperativas de estudantes."], ["E", "o educador \"deposita\" conteúdos nos educandos, vistos como recipientes passivos, sem diálogo nem problematização da realidade."]]},
{"id": "AU-cf3c1355db", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A pedagogia libertária, uma das tendências progressistas na classificação de Libâneo, defende", "gabarito": "A", "comentario": "A ênfase está na vivência grupal e na participação, mais do que nos conteúdos formais.", "alternativas": [["A", "a autogestão pedagógica e a recusa a formas autoritárias de poder, com os grupos de estudantes decidindo sobre a própria aprendizagem."], ["B", "a centralidade da transmissão de conteúdos pelo professor."], ["C", "a instrução programada e o uso de máquinas de ensinar."], ["D", "a obediência a normas fixadas exclusivamente pela direção."], ["E", "a memorização de conteúdos clássicos como fim em si mesma."]]},
{"id": "AU-e9c89aec2f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A pedagogia crítico-social dos conteúdos, defendida por José Carlos Libâneo, propõe que", "gabarito": "A", "comentario": "A tendência valoriza o papel do professor como mediador entre o estudante e o saber sistematizado.", "alternativas": [["A", "a escola garanta a apropriação crítica dos conteúdos culturais universais, relacionando-os à realidade social dos estudantes."], ["B", "os conteúdos sejam deixados em segundo plano em favor apenas das relações afetivas."], ["C", "o estudante aprenda sozinho, sem a mediação do professor."], ["D", "o ensino se limite a treinar comportamentos observáveis."], ["E", "a escola evite discutir a realidade social."]]},
{"id": "AU-c1506b3942", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na didática da pedagogia histórico-crítica, sistematizada a partir de Dermeval Saviani, o trabalho pedagógico parte", "gabarito": "D", "comentario": "A catarse é o momento em que o estudante expressa a nova compreensão do conteúdo.", "alternativas": [["A", "dos interesses espontâneos de cada estudante, sem conteúdos definidos."], ["B", "de objetivos comportamentais, medidos por testes padronizados."], ["C", "da livre escolha dos estudantes, sem participação do professor."], ["D", "da prática social, passa pela problematização, pela instrumentalização e pela catarse, e retorna à prática social, agora compreendida de forma mais elaborada."], ["E", "da memorização de definições, seguida de exercícios de fixação e prova final."]]},
{"id": "AU-75b87ff555", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O Manifesto dos Pioneiros da Educação Nova, de 1932, assinado por educadores como Anísio Teixeira e Fernando de Azevedo, defendia", "gabarito": "D", "comentario": "O documento influenciou o debate sobre a educação pública no Brasil por décadas.", "alternativas": [["A", "o ensino religioso obrigatório em todas as escolas."], ["B", "a educação exclusiva das elites para formar dirigentes."], ["C", "a substituição dos professores por técnicos de ensino."], ["D", "uma escola pública, laica, gratuita e obrigatória, organizada segundo os princípios da Escola Nova."], ["E", "o fim da escola pública e a privatização do ensino."]]},
{"id": "AU-58f5bf9fdc", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo Jean Piaget, uma criança de 9 anos que já compreende a conservação da quantidade, mas ainda precisa de objetos concretos para raciocinar, encontra-se no estágio", "gabarito": "D", "comentario": "Os estágios de Piaget são: sensório-motor (até cerca de 2 anos), pré-operatório (2 a 7), operatório concreto (7 a 11 ou 12) e operatório formal (a partir dos 12).", "alternativas": [["A", "pré-operatório."], ["B", "operatório formal."], ["C", "simbólico-afetivo."], ["D", "operatório concreto."], ["E", "sensório-motor."]]},
{"id": "AU-d85b73a028", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para Piaget, a acomodação é o processo pelo qual", "gabarito": "C", "comentario": "Na assimilação, o novo é incorporado aos esquemas existentes; na acomodação, os esquemas mudam. A equilibração regula as duas.", "alternativas": [["A", "a criança repete comportamentos reforçados pelo adulto."], ["B", "o conhecimento é transmitido do adulto para a criança."], ["C", "o sujeito modifica seus esquemas para dar conta de um objeto ou situação nova que não se encaixava nos esquemas existentes."], ["D", "o sujeito incorpora o novo aos esquemas que já tem, sem modificá-los."], ["E", "o professor organiza o espaço da sala de aula."]]},
{"id": "AU-0ea5a2f3c7", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O egocentrismo, a dificuldade de se colocar no ponto de vista do outro e o animismo, atribuir vida e intenção a objetos, são característicos, segundo Piaget, do estágio", "gabarito": "D", "comentario": "No pré-operatório, desenvolve-se a função simbólica (linguagem, faz de conta, desenho), mas o pensamento ainda é centrado no próprio ponto de vista.", "alternativas": [["A", "operatório concreto."], ["B", "operatório formal."], ["C", "pós-formal."], ["D", "pré-operatório."], ["E", "sensório-motor."]]},
{"id": "AU-4ac1acddb1", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para Lev Vygotsky, a zona de desenvolvimento proximal (ZDP) corresponde", "gabarito": "C", "comentario": "O bom ensino, para Vygotsky, atua na ZDP, adiantando-se ao desenvolvimento e puxando-o.", "alternativas": [["A", "ao espaço físico da sala de aula destinado às atividades em grupo."], ["B", "ao período em que a criança aprende apenas por imitação, sem compreensão."], ["C", "à distância entre o que a criança faz sozinha (desenvolvimento real) e o que consegue fazer com a ajuda de um adulto ou de colegas mais experientes (desenvolvimento potencial)."], ["D", "ao conjunto de conhecimentos já consolidados pela criança."], ["E", "à idade em que a criança começa a falar."]]},
{"id": "AU-920dc30487", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na perspectiva histórico-cultural de Vygotsky, o desenvolvimento das funções psicológicas superiores", "gabarito": "D", "comentario": "Atenção voluntária, memória lógica e pensamento abstrato aparecem primeiro nas relações entre pessoas e depois são internalizados.", "alternativas": [["A", "ocorre igualmente em todas as culturas, sem relação com a história."], ["B", "resulta exclusivamente de reforços positivos e negativos."], ["C", "é determinado pela hereditariedade, e a escola pouco interfere."], ["D", "tem origem social e é mediado por instrumentos e signos, especialmente a linguagem."], ["E", "depende apenas da maturação biológica, sem influência do meio."]]},
{"id": "AU-bff09460fd", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Uma implicação pedagógica das ideias de Vygotsky é", "gabarito": "D", "comentario": "O colega mais experiente pode atuar na zona de desenvolvimento proximal de quem está aprendendo.", "alternativas": [["A", "esperar que a criança amadureça para só então ensinar."], ["B", "evitar a intervenção do professor, para não atrapalhar o desenvolvimento."], ["C", "basear o ensino na punição dos erros."], ["D", "valorizar a interação entre os estudantes, como em grupos de trabalho em que colegas com níveis diferentes colaboram entre si."], ["E", "separar sempre os estudantes por nível de desempenho, sem interação."]]},
{"id": "AU-5caf54e11a", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Henri Wallon destacou, em sua teoria do desenvolvimento,", "gabarito": "C", "comentario": "Para Wallon, a criança deve ser vista como pessoa completa: afeto, ato motor e conhecimento se desenvolvem juntos.", "alternativas": [["A", "a existência de inteligências independentes umas das outras."], ["B", "a aprendizagem como simples memorização."], ["C", "a afetividade e a emoção, ao lado da cognição e do movimento, como dimensões integradas da pessoa."], ["D", "apenas o desenvolvimento lógico-matemático."], ["E", "o condicionamento operante como base de toda aprendizagem."]]},
{"id": "AU-3fcd4e1880", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para David Ausubel, a aprendizagem significativa ocorre quando", "gabarito": "D", "comentario": "Ausubel propôs os organizadores prévios para ligar o que o estudante já sabe ao que vai aprender. O oposto é a aprendizagem mecânica.", "alternativas": [["A", "o professor usa apenas recompensas e punições."], ["B", "o conteúdo é apresentado sem nenhuma organização prévia."], ["C", "o estudante repete o conteúdo até decorá-lo."], ["D", "a nova informação se relaciona, de modo não arbitrário, com conhecimentos relevantes que o estudante já possui (subsunçores)."], ["E", "o estudante memoriza a informação literalmente, sem relacioná-la a nada."]]},
{"id": "AU-a45c6bda07", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "No condicionamento operante de B. F. Skinner, o reforço negativo consiste em", "gabarito": "D", "comentario": "Todo reforço aumenta a frequência do comportamento. O reforço positivo acrescenta algo agradável; o negativo retira algo desagradável. Punição é outra coisa.", "alternativas": [["A", "dar um prêmio depois de um comportamento desejado."], ["B", "ignorar um comportamento até que ele desapareça."], ["C", "aumentar a frequência de um comportamento por meio de ameaças."], ["D", "retirar um estímulo desagradável depois de um comportamento, aumentando a chance de ele se repetir."], ["E", "aplicar um castigo para diminuir um comportamento."]]},
{"id": "AU-59c7604ff7", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A teoria das inteligências múltiplas, de Howard Gardner, sustenta que", "gabarito": "A", "comentario": "Para a escola, a teoria sugere diversificar estratégias e reconhecer diferentes formas de aprender e de se expressar.", "alternativas": [["A", "há diferentes tipos de inteligência, como a linguística, a lógico-matemática, a espacial, a musical, a corporal-cinestésica, a interpessoal e a intrapessoal."], ["B", "a inteligência é única e pode ser medida por um teste de QI."], ["C", "apenas a inteligência lógico-matemática deve ser valorizada na escola."], ["D", "a inteligência é fixa e não se desenvolve com a educação."], ["E", "as inteligências dependem exclusivamente do ambiente familiar."]]},
{"id": "AU-2340e22f3c", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo a psicogênese da língua escrita, de Emilia Ferreiro e Ana Teberosky, uma criança que escreve \"OA\" para \"bola\", usando uma letra para cada sílaba, com valor sonoro, está no nível", "gabarito": "C", "comentario": "No nível silábico, cada sílaba é representada por uma letra. No silábico-alfabético, a criança alterna sílabas completas e incompletas.", "alternativas": [["A", "alfabético."], ["B", "ortográfico."], ["C", "silábico."], ["D", "pré-silábico."], ["E", "silábico-alfabético."]]},
{"id": "AU-a3b6629e6c", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Em \"Pedagogia da Autonomia\", Paulo Freire afirma que ensinar não é", "gabarito": "E", "comentario": "Na mesma obra, Freire diz que ensinar exige pesquisa, respeito aos saberes dos educandos, reflexão crítica sobre a prática e diálogo.", "alternativas": [["A", "uma atividade que exija pesquisa ou reflexão sobre a prática."], ["B", "um ato político nem ético."], ["C", "uma tarefa que dependa do diálogo com os educandos."], ["D", "algo que exija respeito aos saberes dos educandos."], ["E", "transferir conhecimento, mas criar as possibilidades para a sua própria produção ou a sua construção."]]},
{"id": "AU-c8d5bf6538", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na perspectiva construtivista, o erro do estudante deve ser entendido como", "gabarito": "B", "comentario": "Analisar o erro mostra como o estudante está pensando, o que orienta a intervenção do professor.", "alternativas": [["A", "motivo suficiente para a reprovação imediata."], ["B", "expressão das hipóteses que ele formula sobre o objeto de conhecimento, sendo uma fonte de informação para o professor planejar a intervenção."], ["C", "falta de esforço, que deve ser punida."], ["D", "sinal de que o estudante não tem capacidade de aprender."], ["E", "algo a ser ignorado, para não constranger o estudante."]]},
{"id": "AU-4335fbadf0", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A metacognição, cada vez mais valorizada no ensino, pode ser definida como", "gabarito": "E", "comentario": "Perguntas como \"o que eu já sei?\", \"o que ainda não entendi?\" e \"como posso estudar melhor?\" estimulam a metacognição.", "alternativas": [["A", "a memorização de grande quantidade de informações."], ["B", "a aprendizagem que ocorre só com o uso de tecnologia."], ["C", "o conhecimento das regras da escola."], ["D", "a cópia de resumos feitos pelo professor."], ["E", "a capacidade de refletir sobre o próprio pensamento e o próprio processo de aprendizagem, monitorando e ajustando as estratégias usadas."]]},
{"id": "AU-f0839f85bf", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na perspectiva construtivista, o conhecimento é entendido como", "gabarito": "E", "comentario": "No construtivismo, o estudante é sujeito ativo, e o professor organiza situações que provoquem a construção do conhecimento.", "alternativas": [["A", "um conjunto de informações transmitidas e memorizadas passivamente."], ["B", "resultado exclusivo da maturação biológica."], ["C", "algo inato, que apenas se manifesta com a idade."], ["D", "produto de reforços e punições aplicados pelo professor."], ["E", "construído pelo sujeito na interação com o objeto de conhecimento e com o meio, e não apenas recebido pronto."]]},
{"id": "AU-38b9c4dd42", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na Base Nacional Comum Curricular (BNCC), competência é definida como", "gabarito": "E", "comentario": "A BNCC organiza as aprendizagens essenciais em competências gerais, competências específicas e habilidades.", "alternativas": [["A", "o conjunto de conteúdos mínimos que devem ser memorizados em cada ano."], ["B", "a nota mínima para aprovação em cada componente curricular."], ["C", "a lista de livros didáticos que cada escola deve adotar."], ["D", "a capacidade inata de cada estudante, que a escola apenas identifica."], ["E", "a mobilização de conhecimentos, habilidades, atitudes e valores para resolver demandas complexas da vida cotidiana, do pleno exercício da cidadania e do mundo do trabalho."]]},
{"id": "AU-47c4ef2879", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A BNCC estabelece, para toda a educação básica, um conjunto de", "gabarito": "C", "comentario": "As dez competências gerais atravessam todas as etapas e componentes, da educação infantil ao ensino médio.", "alternativas": [["A", "doze competências gerais."], ["B", "quinze competências gerais."], ["C", "dez competências gerais."], ["D", "cinco competências gerais."], ["E", "oito competências gerais."]]},
{"id": "AU-4cb30e363b", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Sobre a relação entre a BNCC e os currículos, é correto afirmar que", "gabarito": "C", "comentario": "BNCC e currículos se complementam: a Base diz o que é essencial; o currículo diz como, considerando o contexto.", "alternativas": [["A", "a BNCC substitui o projeto político-pedagógico das escolas."], ["B", "a BNCC vale apenas para as escolas privadas."], ["C", "a BNCC é referência obrigatória para a elaboração dos currículos, que são construídos pelas redes e escolas considerando a realidade local."], ["D", "a BNCC é o próprio currículo de cada escola, e não pode ser complementada."], ["E", "a BNCC é apenas uma sugestão, sem caráter obrigatório."]]},
{"id": "AU-76c7b9364f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na BNCC, a habilidade identificada pelo código EF06CI01 refere-se", "gabarito": "A", "comentario": "O primeiro par de letras indica a etapa (EF ou EI); os números, o ano ou bloco de anos; as letras seguintes, o componente; os últimos números, a posição da habilidade.", "alternativas": [["A", "ao ensino fundamental, 6º ano, componente Ciências, habilidade número 01."], ["B", "à educação física, 6ª série, ciclo inicial, módulo 01."], ["C", "ao ensino fundamental, 6 aulas semanais, ciências integradas, unidade 01."], ["D", "à educação infantil, grupo 6, campo de experiência 01."], ["E", "ao ensino médio, 6º semestre, competência 01."]]},
{"id": "AU-abd49677dc", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na educação infantil, a BNCC estabelece seis direitos de aprendizagem e desenvolvimento:", "gabarito": "C", "comentario": "Esses direitos garantem condições para que as crianças aprendam em situações em que desempenhem papel ativo.", "alternativas": [["A", "cuidar, alimentar, dormir, higienizar, brincar e passear."], ["B", "falar, ouvir, ler, escrever, calcular e pesquisar."], ["C", "conviver, brincar, participar, explorar, expressar e conhecer-se."], ["D", "ler, escrever, contar, desenhar, cantar e obedecer."], ["E", "observar, memorizar, repetir, copiar, revisar e avaliar."]]},
{"id": "AU-075ad3e9e5", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A organização curricular da educação infantil na BNCC se dá por", "gabarito": "A", "comentario": "Os cinco campos são: O eu, o outro e o nós; Corpo, gestos e movimentos; Traços, sons, cores e formas; Escuta, fala, pensamento e imaginação; Espaços, tempos, quantidades, relações e transformações.", "alternativas": [["A", "campos de experiências, como \"O eu, o outro e o nós\" e \"Corpo, gestos e movimentos\"."], ["B", "disciplinas, como Português e Matemática."], ["C", "áreas do conhecimento, como Linguagens e Ciências da Natureza."], ["D", "itinerários formativos escolhidos pelas famílias."], ["E", "listas de conteúdos a serem memorizados."]]},
{"id": "AU-0d0015c3be", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo as Diretrizes Curriculares Nacionais da Educação Infantil e a BNCC, os eixos estruturantes das práticas pedagógicas na educação infantil são", "gabarito": "E", "comentario": "É por meio de interações e brincadeiras que as crianças constroem e se apropriam de conhecimentos.", "alternativas": [["A", "a leitura e a escrita."], ["B", "a disciplina e a obediência."], ["C", "a memorização e a repetição."], ["D", "as provas e as notas."], ["E", "as interações e a brincadeira."]]},
{"id": "AU-73d9cd1005", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo a BNCC, nos dois primeiros anos do ensino fundamental, a ação pedagógica deve ter como foco", "gabarito": "D", "comentario": "A alfabetização articulada ao letramento é prioridade no início do ensino fundamental.", "alternativas": [["A", "o ensino de língua estrangeira."], ["B", "a reprovação dos estudantes que não leem."], ["C", "a memorização das regras gramaticais."], ["D", "a alfabetização, para garantir amplas oportunidades de apropriação do sistema de escrita alfabética."], ["E", "a preparação para avaliações externas de larga escala."]]},
{"id": "AU-4c3ff82754", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Os Temas Contemporâneos Transversais (TCTs), que acompanham a BNCC, como educação ambiental, educação financeira e direitos da criança e do adolescente, devem ser trabalhados", "gabarito": "A", "comentario": "Os TCTs ajudam a dar sentido aos conteúdos, relacionando-os a questões da vida em sociedade.", "alternativas": [["A", "de forma transversal e integradora, articulados aos componentes curriculares e contextualizados."], ["B", "como disciplinas novas e obrigatórias, com professor próprio."], ["C", "apenas em datas comemorativas."], ["D", "somente no ensino médio."], ["E", "apenas quando houver tempo livre no calendário."]]},
{"id": "AU-3176ec431c", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · BNCC", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Entre as competências gerais da BNCC, está a de exercitar a empatia, o diálogo, a resolução de conflitos e a cooperação. Ela se relaciona diretamente", "gabarito": "D", "comentario": "A BNCC reconhece que a educação deve tratar do desenvolvimento integral, incluindo as dimensões emocional e social.", "alternativas": [["A", "à memorização de datas históricas."], ["B", "ao uso de laboratórios de ciências."], ["C", "à preparação exclusiva para o mercado de trabalho."], ["D", "ao desenvolvimento de competências socioemocionais e à convivência respeitosa com a diversidade."], ["E", "ao domínio de técnicas de cálculo mental."]]},
{"id": "AU-5a86dbeb3c", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diretrizes Curriculares Nacionais", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo as Diretrizes Curriculares Nacionais Gerais para a Educação Básica, são modalidades da educação básica, entre outras,", "gabarito": "D", "comentario": "Educação infantil, fundamental e médio são etapas. As modalidades atravessam as etapas, atendendo a públicos e contextos específicos.", "alternativas": [["A", "a pós-graduação, o mestrado e o doutorado."], ["B", "o ensino religioso, a educação física e a arte."], ["C", "os cursos livres de idiomas e de informática."], ["D", "a educação de jovens e adultos, a educação especial, a educação do campo, a educação escolar indígena e a educação escolar quilombola."], ["E", "a educação infantil, o ensino fundamental e o ensino médio."]]},
{"id": "AU-955f3e0d81", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diretrizes Curriculares Nacionais", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo as Diretrizes Curriculares Nacionais da educação básica, a base nacional comum e a parte diversificada do currículo", "gabarito": "D", "comentario": "A parte diversificada enriquece e complementa a base comum com as características regionais e locais.", "alternativas": [["A", "são independentes, e a parte diversificada é opcional."], ["B", "devem ser avaliadas por instrumentos totalmente diferentes."], ["C", "só se integram no ensino superior."], ["D", "constituem um todo integrado e não podem ser consideradas como dois blocos distintos."], ["E", "devem ser ensinadas em turnos separados."]]},
{"id": "AU-c0298ac3c3", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diretrizes Curriculares Nacionais", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "As Diretrizes Curriculares Nacionais para a Educação Infantil concebem a criança como", "gabarito": "B", "comentario": "Essa concepção orienta práticas que articulam cuidar e educar.", "alternativas": [["A", "alguém sem capacidade de aprender antes do ensino fundamental."], ["B", "sujeito histórico e de direitos, que constrói sua identidade e produz cultura nas interações e práticas cotidianas."], ["C", "um adulto em miniatura, que deve ser preparado para o trabalho."], ["D", "um ser passivo, que apenas recebe cuidados."], ["E", "um aluno que deve ser alfabetizado antes dos 4 anos."]]},
{"id": "AU-c0fd8900c8", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Planejamento", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Entre os níveis de planejamento educacional, o mais detalhado, que organiza as atividades de um encontro com a turma, é", "gabarito": "C", "comentario": "O planejamento vai do mais amplo (sistema de ensino, escola) ao mais específico (plano de ensino e plano de aula).", "alternativas": [["A", "o plano de ensino anual."], ["B", "o regimento escolar."], ["C", "o plano de aula."], ["D", "o plano nacional de educação."], ["E", "o projeto político-pedagógico."]]},
{"id": "AU-3c59074c13", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Planejamento", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "São elementos essenciais de um plano de aula:", "gabarito": "B", "comentario": "Os elementos precisam ser coerentes entre si: a avaliação, por exemplo, deve verificar os objetivos propostos.", "alternativas": [["A", "somente as atividades de casa."], ["B", "objetivos, conteúdos, procedimentos metodológicos, recursos e avaliação."], ["C", "apenas a lista de conteúdos e a data da prova."], ["D", "o regimento da escola e o calendário de feriados."], ["E", "a lista de presença e as notas do bimestre anterior."]]},
{"id": "AU-fc816b4688", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Planejamento", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na formulação dos objetivos de aprendizagem, recomenda-se", "gabarito": "E", "comentario": "Objetivos claros orientam a escolha das atividades e dos instrumentos de avaliação.", "alternativas": [["A", "descrever apenas o que o professor vai fazer na aula."], ["B", "usar verbos vagos, como \"saber tudo sobre o assunto\"."], ["C", "evitar objetivos, para não engessar a aula."], ["D", "copiar os objetivos do ano anterior sem revisão."], ["E", "usar verbos que indiquem o que o estudante deverá ser capaz de fazer, como identificar, comparar, explicar ou resolver."]]},
{"id": "AU-df8617f697", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Planejamento", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na taxonomia de Bloom revisada, os processos cognitivos estão organizados em ordem crescente de complexidade:", "gabarito": "C", "comentario": "A taxonomia ajuda a planejar objetivos e atividades que vão além da memorização.", "alternativas": [["A", "entender, lembrar, analisar, aplicar, criar e avaliar."], ["B", "avaliar, criar, lembrar, entender, aplicar e analisar."], ["C", "lembrar, entender, aplicar, analisar, avaliar e criar."], ["D", "criar, avaliar, analisar, aplicar, entender e lembrar."], ["E", "aplicar, lembrar, criar, entender, avaliar e analisar."]]},
{"id": "AU-939edc83bc", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Planejamento", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Sobre o planejamento de ensino, é correto afirmar que ele deve ser", "gabarito": "E", "comentario": "Planejar não é preencher formulários: é antecipar, organizar e reorganizar o trabalho a partir da realidade.", "alternativas": [["A", "rígido, cumprido à risca mesmo que a turma não esteja aprendendo."], ["B", "feito uma única vez, no início da carreira do professor."], ["C", "elaborado apenas pela direção, sem participação dos professores."], ["D", "dispensável, porque cada aula é imprevisível."], ["E", "flexível, revisto continuamente a partir da avaliação e das necessidades da turma."]]},
{"id": "AU-9a82d1821a", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Planejamento", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A sequência didática, segundo Antoni Zabala, pode ser entendida como", "gabarito": "E", "comentario": "A análise das sequências permite avaliar a coerência entre atividades, objetivos e concepção de aprendizagem.", "alternativas": [["A", "uma lista de exercícios repetitivos aplicada ao fim do bimestre."], ["B", "a ordem dos capítulos do livro didático."], ["C", "o horário semanal das aulas da turma."], ["D", "uma prova dividida em várias partes."], ["E", "um conjunto de atividades ordenadas, estruturadas e articuladas para atingir determinados objetivos educacionais, com início e fim conhecidos."]]},
{"id": "AU-acd5a7717a", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Planejamento", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O plano de ensino (ou plano de curso) caracteriza-se por", "gabarito": "C", "comentario": "O plano de ensino se apoia no PPP e no currículo e se desdobra nos planos de aula.", "alternativas": [["A", "tratar só das normas de convivência da escola."], ["B", "substituir o projeto político-pedagógico."], ["C", "organizar o trabalho de um componente curricular ao longo de um período, como o ano ou o semestre, com objetivos, conteúdos, metodologia e avaliação."], ["D", "detalhar apenas uma aula específica."], ["E", "definir a política educacional de todo o município."]]},
{"id": "AU-c01489a51e", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Projeto político-pedagógico", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O projeto político-pedagógico (PPP) da escola deve ser", "gabarito": "E", "comentario": "É político porque assume compromissos com a formação do cidadão; é pedagógico porque define as ações educativas.", "alternativas": [["A", "elaborado apenas pela secretaria de educação e enviado pronto às escolas."], ["B", "escrito pelo diretor, sozinho, para cumprir uma exigência burocrática."], ["C", "idêntico em todas as escolas do país."], ["D", "elaborado uma vez e nunca mais revisto."], ["E", "construído coletivamente pela comunidade escolar, expressando a identidade, as intenções e a organização do trabalho da escola."]]},
{"id": "AU-056f259de6", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Projeto político-pedagógico", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para Ilma Passos Veiga, o projeto político-pedagógico", "gabarito": "A", "comentario": "O PPP é um processo permanente de reflexão e discussão dos problemas da escola.", "alternativas": [["A", "vai além de um agrupamento de planos de ensino e de atividades: é uma ação intencional, com um compromisso definido coletivamente."], ["B", "é um documento a ser arquivado depois de aprovado."], ["C", "deve ser copiado de escolas com melhores resultados."], ["D", "trata apenas da parte administrativa da escola."], ["E", "dispensa a participação dos professores."]]},
{"id": "AU-9601d63f43", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Projeto político-pedagógico", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na construção do projeto político-pedagógico, o diagnóstico da realidade da escola serve para", "gabarito": "A", "comentario": "O PPP costuma articular o marco referencial (o que se deseja), o diagnóstico (o que se tem) e a programação (o que fazer).", "alternativas": [["A", "conhecer a situação atual da escola e da comunidade, identificando necessidades e prioridades para as ações planejadas."], ["B", "classificar os professores do melhor para o pior."], ["C", "selecionar os estudantes que poderão permanecer na escola."], ["D", "substituir o planejamento das aulas."], ["E", "definir o valor das mensalidades."]]},
{"id": "AU-47f53be8bc", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Currículo", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O chamado currículo oculto corresponde", "gabarito": "A", "comentario": "A organização do espaço, as regras e o modo como as relações acontecem também ensinam.", "alternativas": [["A", "às aprendizagens de normas, valores e atitudes que ocorrem na escola sem estarem explicitadas nos planos e documentos oficiais."], ["B", "ao conteúdo que o professor esconde dos estudantes até a prova."], ["C", "às disciplinas optativas que não aparecem no histórico."], ["D", "aos documentos sigilosos da secretaria de educação."], ["E", "ao currículo das escolas particulares."]]},
{"id": "AU-c75573db0c", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Currículo", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na distinção entre currículo formal, real e oculto, o currículo real é", "gabarito": "A", "comentario": "O currículo formal é o prescrito nos documentos; o real é o vivido; o oculto é o que se aprende sem estar explícito.", "alternativas": [["A", "o que efetivamente acontece na sala de aula, a partir do que foi planejado e das condições concretas de ensino."], ["B", "o currículo estabelecido nas leis e diretrizes oficiais, apenas."], ["C", "o conjunto de livros didáticos adotados pela escola."], ["D", "o currículo idealizado pelos especialistas."], ["E", "o que o estudante aprende fora da escola, apenas."]]},
{"id": "AU-a5eca2b13f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Currículo", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Nas teorias críticas do currículo, ele é entendido como", "gabarito": "D", "comentario": "Perguntar \"por que esse conhecimento e não outro?\" é central nas teorias críticas e pós-críticas.", "alternativas": [["A", "algo definido pela natureza, sem relação com a sociedade."], ["B", "um documento que não influencia a formação dos estudantes."], ["C", "uma questão exclusivamente administrativa."], ["D", "uma construção social e histórica, não neutra, que envolve escolhas e relações de poder sobre quais conhecimentos são considerados válidos."], ["E", "uma lista neutra e técnica de conteúdos científicos."]]},
{"id": "AU-b8e6d032ed", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Currículo", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo a LDB, a parte diversificada dos currículos deve ser definida pelos sistemas de ensino e pelas escolas, considerando", "gabarito": "E", "comentario": "É o art. 26 da LDB. A história e a cultura da região são exemplos de temas da parte diversificada.", "alternativas": [["A", "apenas o conteúdo das avaliações nacionais."], ["B", "exclusivamente as preferências do diretor."], ["C", "os conteúdos de outros países."], ["D", "o currículo do ensino superior."], ["E", "as características regionais e locais da sociedade, da cultura, da economia e dos educandos."]]},
{"id": "AU-e0d08f96fc", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A avaliação diagnóstica, realizada geralmente no início de um período ou de uma unidade, tem como principal finalidade", "gabarito": "C", "comentario": "Saber de onde os estudantes partem permite planejar intervenções mais adequadas.", "alternativas": [["A", "aprovar ou reprovar os estudantes."], ["B", "substituir o planejamento do professor."], ["C", "identificar os conhecimentos prévios e as dificuldades dos estudantes, para orientar o planejamento."], ["D", "atribuir a nota final do bimestre."], ["E", "classificar os estudantes para formar turmas fixas por desempenho."]]},
{"id": "AU-8fa51fc838", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A avaliação formativa caracteriza-se por", "gabarito": "A", "comentario": "A avaliação formativa regula a aprendizagem enquanto ela acontece.", "alternativas": [["A", "acontecer ao longo do processo, oferecendo retorno ao estudante e informações ao professor para ajustar o ensino."], ["B", "ocorrer apenas no fim do ano, para certificar a aprovação."], ["C", "servir somente para classificar os estudantes."], ["D", "ser aplicada exclusivamente por meio de provas objetivas."], ["E", "dispensar o diálogo com os estudantes sobre seus erros."]]},
{"id": "AU-73bd0fed57", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A avaliação somativa tem como característica", "gabarito": "D", "comentario": "Diagnóstica, formativa e somativa não se excluem: cada uma tem uma função no processo.", "alternativas": [["A", "acompanhar o processo diariamente, sem registro de resultados."], ["B", "ser feita apenas pelos próprios estudantes."], ["C", "não ter nenhuma relação com os objetivos de ensino."], ["D", "ocorrer ao final de um período ou unidade, com a finalidade de verificar e registrar os resultados alcançados."], ["E", "ocorrer antes do início das aulas, para conhecer a turma."]]},
{"id": "AU-07c8935690", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Cipriano Luckesi diferencia o ato de avaliar do ato de examinar. Para o autor,", "gabarito": "E", "comentario": "Para Luckesi, a avaliação é diagnóstica e inclusiva; o exame é classificatório e excludente.", "alternativas": [["A", "examinar e avaliar são exatamente a mesma coisa."], ["B", "a avaliação deve servir principalmente para punir os estudantes."], ["C", "o exame é a forma mais justa de incluir os estudantes."], ["D", "a avaliação deve ocorrer só no fim do ano letivo."], ["E", "o exame classifica e seleciona, enquanto a avaliação diagnostica a situação de aprendizagem para subsidiar decisões que levem o estudante a aprender."]]},
{"id": "AU-4e76092a0f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A avaliação mediadora, proposta por Jussara Hoffmann, caracteriza-se por", "gabarito": "C", "comentario": "Na avaliação mediadora, o professor analisa as produções dos estudantes e propõe novos desafios a partir delas.", "alternativas": [["A", "comparar os estudantes entre si para formar um ranking."], ["B", "dispensar o registro do desenvolvimento dos estudantes."], ["C", "acompanhar o processo de construção do conhecimento, com diálogo e intervenção do professor a partir das respostas dos estudantes."], ["D", "atribuir notas sem nenhum retorno aos estudantes."], ["E", "limitar-se a uma única prova no fim do bimestre."]]},
{"id": "AU-6dad37c3f3", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Um retorno (feedback) que contribui efetivamente para a aprendizagem é aquele que", "gabarito": "A", "comentario": "O feedback deve mostrar onde o estudante está, aonde precisa chegar e como chegar lá.", "alternativas": [["A", "é específico, dado em tempo oportuno e indica ao estudante o que fazer para melhorar."], ["B", "se limita a uma nota, sem comentários."], ["C", "compara o estudante publicamente com os colegas."], ["D", "é dado meses depois da atividade."], ["E", "aponta apenas os erros, sem orientação."]]},
{"id": "AU-bbfef80c2c", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A autoavaliação, quando incorporada à prática pedagógica, contribui para", "gabarito": "A", "comentario": "A autoavaliação estimula a metacognição e a responsabilidade pela própria aprendizagem.", "alternativas": [["A", "desenvolver a autonomia e a capacidade do estudante de refletir sobre o próprio processo de aprendizagem."], ["B", "substituir completamente a avaliação feita pelo professor."], ["C", "aumentar artificialmente as notas da turma."], ["D", "dispensar o professor de planejar."], ["E", "punir os estudantes que se avaliam mal."]]},
{"id": "AU-c67cd6df94", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Quanto aos instrumentos de avaliação, é recomendável", "gabarito": "C", "comentario": "Instrumentos variados permitem que estudantes com diferentes formas de expressão mostrem o que aprenderam.", "alternativas": [["A", "aplicar sempre o mesmo instrumento, para todos os conteúdos."], ["B", "evitar registrar as observações feitas em sala."], ["C", "diversificá-los, combinando, por exemplo, provas, trabalhos, observação, portfólios e apresentações, para captar diferentes aprendizagens."], ["D", "usar apenas provas escritas objetivas, por serem as únicas confiáveis."], ["E", "avaliar somente o comportamento dos estudantes."]]},
{"id": "AU-cf4138414f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O conselho de classe é", "gabarito": "C", "comentario": "O conselho de classe deve olhar também para as práticas de ensino, e não só para o desempenho dos estudantes.", "alternativas": [["A", "uma reunião de pais para escolher o diretor."], ["B", "um espaço apenas para entrega de boletins."], ["C", "uma instância colegiada em que professores e equipe pedagógica analisam o processo de ensino e aprendizagem das turmas e definem intervenções."], ["D", "uma reunião apenas para decidir castigos aos estudantes indisciplinados."], ["E", "um órgão da secretaria de educação que fiscaliza as escolas."]]},
{"id": "AU-8579251f38", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Os estudos de recuperação, para cumprirem sua finalidade pedagógica, devem", "gabarito": "D", "comentario": "A LDB prevê recuperação de preferência paralela ao período letivo, para corrigir as dificuldades a tempo.", "alternativas": [["A", "ocorrer apenas no fim do ano, depois das notas fechadas."], ["B", "ser oferecidos somente aos estudantes que pedirem."], ["C", "servir para reduzir a nota dos estudantes que faltaram."], ["D", "retomar os conteúdos não aprendidos com novas estratégias, e não apenas repetir a prova."], ["E", "limitar-se à aplicação de uma nova prova igual à anterior."]]},
{"id": "AU-19676bfc14", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O Índice de Desenvolvimento da Educação Básica (Ideb) é calculado a partir", "gabarito": "C", "comentario": "Combinar fluxo e desempenho evita que a escola melhore o índice reprovando mais ou aprovando sem aprendizagem.", "alternativas": [["A", "das notas atribuídas pelos professores nos boletins."], ["B", "do valor investido por estudante."], ["C", "das taxas de aprovação (fluxo escolar) e das médias de desempenho nas avaliações do Saeb."], ["D", "apenas do número de matrículas de cada escola."], ["E", "da quantidade de professores com pós-graduação."]]},
{"id": "AU-4a3e4cb737", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Metodologias de ensino", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na aprendizagem baseada em problemas,", "gabarito": "A", "comentario": "O problema é o ponto de partida da aprendizagem, e não um exercício de aplicação ao final.", "alternativas": [["A", "os estudantes partem de um problema, de preferência real, e buscam conhecimentos para analisá-lo e propor soluções, geralmente em grupos."], ["B", "o professor apresenta toda a teoria antes e depois aplica uma prova."], ["C", "os problemas são resolvidos individualmente, sem discussão."], ["D", "os estudantes apenas copiam soluções prontas do livro."], ["E", "o conteúdo é decorado antes de qualquer atividade."]]},
{"id": "AU-f7378ef30c", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Metodologias de ensino", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A pedagogia de projetos, defendida por autores como Fernando Hernández, caracteriza-se por", "gabarito": "E", "comentario": "Os projetos favorecem o protagonismo, a pesquisa e a integração entre conhecimentos.", "alternativas": [["A", "seguir rigidamente a ordem dos capítulos do livro didático."], ["B", "dispensar o planejamento e os objetivos de aprendizagem."], ["C", "limitar-se a trabalhos de pesquisa copiados da internet."], ["D", "trabalhar apenas uma disciplina por vez, sem relação com as outras."], ["E", "organizar a aprendizagem em torno de uma questão ou problema, com participação dos estudantes no planejamento, articulação entre áreas e um produto final."]]},
{"id": "AU-8bf811eca0", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Metodologias de ensino", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A aula expositiva dialogada diferencia-se da aula expositiva tradicional porque", "gabarito": "A", "comentario": "A exposição continua presente, mas o diálogo torna a aprendizagem mais ativa.", "alternativas": [["A", "estimula a participação dos estudantes, com perguntas, discussão e relação com seus conhecimentos prévios."], ["B", "dispensa a fala do professor."], ["C", "é feita apenas com vídeos, sem intervenção do professor."], ["D", "proíbe perguntas até o fim da explicação."], ["E", "consiste em ditar o conteúdo para cópia."]]},
{"id": "AU-951b6f6d45", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Metodologias de ensino", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O seminário, como estratégia de ensino, contribui principalmente para", "gabarito": "A", "comentario": "O professor orienta a pesquisa, define critérios e faz a mediação das discussões.", "alternativas": [["A", "desenvolver a pesquisa, a organização das ideias, a oralidade e a autonomia dos estudantes."], ["B", "eliminar a necessidade de orientação do professor."], ["C", "avaliar apenas a memorização do conteúdo."], ["D", "substituir todas as outras atividades do bimestre."], ["E", "reduzir a participação dos estudantes."]]},
{"id": "AU-d979530845", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Metodologias de ensino", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O estudo do meio (ou aula de campo) é uma estratégia que", "gabarito": "D", "comentario": "Envolve preparação (problema e roteiro), a saída em si e a sistematização depois.", "alternativas": [["A", "dispensa planejamento prévio e atividades posteriores."], ["B", "só pode ser realizada em outras cidades."], ["C", "substitui a necessidade de avaliação."], ["D", "permite investigar diretamente a realidade, articulando conhecimentos de diferentes áreas a partir da observação e do registro."], ["E", "serve apenas como passeio recreativo, sem relação com o currículo."]]},
{"id": "AU-30aa44cc69", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Metodologias de ensino", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na aprendizagem cooperativa, um princípio essencial é", "gabarito": "A", "comentario": "Papéis definidos e metas comuns ajudam a evitar que poucos façam tudo pelo grupo.", "alternativas": [["A", "a interdependência positiva, em que o sucesso do grupo depende da contribuição de cada integrante, combinada com a responsabilidade individual."], ["B", "que apenas o estudante mais habilidoso realize a tarefa."], ["C", "a competição entre os membros do mesmo grupo."], ["D", "que cada estudante trabalhe isolado, sem trocar ideias."], ["E", "que o grupo receba nota sem que se saiba o que cada um fez."]]},
{"id": "AU-ac4d9563b1", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Metodologias de ensino", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O estudo de caso, como estratégia de ensino, consiste em", "gabarito": "E", "comentario": "É muito usado para relacionar teoria e prática.", "alternativas": [["A", "memorizar casos famosos para a prova."], ["B", "copiar textos sobre o tema sem discussão."], ["C", "assistir a vídeos sem nenhuma atividade posterior."], ["D", "resolver exercícios mecânicos de repetição."], ["E", "analisar uma situação concreta, real ou simulada, para discutir conceitos, identificar problemas e propor encaminhamentos."]]},
{"id": "AU-07dd4b77d7", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O atendimento educacional especializado (AEE)", "gabarito": "C", "comentario": "O AEE elimina barreiras para a participação do estudante, em articulação com o professor da sala comum.", "alternativas": [["A", "é oferecido apenas em escolas especiais."], ["B", "é destinado a todos os estudantes com dificuldades de aprendizagem."], ["C", "complementa ou suplementa a formação do estudante, não substitui o ensino comum e é oferecido preferencialmente em salas de recursos multifuncionais, no contraturno."], ["D", "substitui a frequência do estudante na sala comum."], ["E", "é um reforço escolar para estudantes com notas baixas."]]},
{"id": "AU-896a2e32d5", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "É público-alvo da educação especial, segundo a política nacional:", "gabarito": "C", "comentario": "Estudantes com dislexia ou TDAH não são público-alvo da educação especial, mas têm direito a acompanhamento integral (Lei n.º 14.254/2021).", "alternativas": [["A", "estudantes que chegam atrasados com frequência."], ["B", "apenas os estudantes com mais de 18 anos."], ["C", "estudantes com deficiência, transtornos globais do desenvolvimento (como o autismo) e altas habilidades ou superdotação."], ["D", "todos os estudantes com notas abaixo da média."], ["E", "apenas os estudantes com deficiência física."]]},
{"id": "AU-653d9163be", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A Lei n.º 14.254/2021 dispõe sobre", "gabarito": "B", "comentario": "A lei prevê identificação precoce, encaminhamento e apoio, com atuação conjunta das áreas de educação e saúde.", "alternativas": [["A", "a obrigatoriedade de medicação para estudantes com TDAH."], ["B", "o acompanhamento integral para educandos com dislexia, transtorno do déficit de atenção com hiperatividade (TDAH) ou outro transtorno de aprendizagem."], ["C", "a criação de escolas separadas para estudantes com TDAH."], ["D", "a proibição de matrícula de estudantes com dislexia."], ["E", "o fim da educação especial na rede regular."]]},
{"id": "AU-4189b62acb", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "As adaptações ou flexibilizações curriculares para estudantes com deficiência devem", "gabarito": "E", "comentario": "Prova ampliada, mais tempo, material concreto e comunicação alternativa são exemplos.", "alternativas": [["A", "retirar o estudante das atividades da turma."], ["B", "reduzir as expectativas a ponto de o estudante não aprender nada novo."], ["C", "ser aplicadas a toda a turma sem avaliação das necessidades."], ["D", "dispensar o planejamento conjunto com o professor do AEE."], ["E", "manter os objetivos essenciais e ajustar estratégias, recursos, tempos e formas de avaliação às necessidades do estudante."]]},
{"id": "AU-32d94d06b8", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O plano educacional individualizado (PEI) é um instrumento que", "gabarito": "E", "comentario": "O PEI orienta e registra o percurso do estudante e deve ser revisto periodicamente.", "alternativas": [["A", "substitui o currículo da turma para todos os estudantes."], ["B", "é elaborado apenas pelo médico do estudante."], ["C", "serve para justificar a exclusão do estudante das aulas."], ["D", "é um laudo que define se o estudante pode estudar."], ["E", "organiza objetivos, estratégias e recursos para um estudante específico, elaborado de forma colaborativa entre professores, equipe pedagógica e família."]]},
{"id": "AU-f9802393c7", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para estudantes com altas habilidades ou superdotação, são estratégias previstas na educação inclusiva", "gabarito": "D", "comentario": "Esses estudantes também são público-alvo da educação especial e têm direito ao AEE.", "alternativas": [["A", "a proibição de atividades extras, para não destacá-lo."], ["B", "a transferência obrigatória para escolas particulares."], ["C", "a redução da carga horária, sem atividades novas."], ["D", "o enriquecimento curricular e a aceleração de estudos, conforme as necessidades do estudante."], ["E", "a retenção do estudante na mesma série, para que ajude os colegas."]]},
{"id": "AU-3f239a5685", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diversidade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "As Diretrizes Curriculares Nacionais para a Educação das Relações Étnico-Raciais orientam as escolas a", "gabarito": "B", "comentario": "As diretrizes complementam a Lei n.º 10.639/2003, depois ampliada pela Lei n.º 11.645/2008, que incluiu a história e a cultura indígena.", "alternativas": [["A", "separar os estudantes por cor nas atividades."], ["B", "combater o racismo e a discriminação e a valorizar a história e a cultura afro-brasileira e africana em todo o currículo."], ["C", "tratar a temática apenas no Dia da Consciência Negra."], ["D", "abordar o tema somente nas aulas de história."], ["E", "evitar falar sobre racismo, para não gerar conflitos."]]},
{"id": "AU-2e52a37de4", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diversidade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Uma prática pedagógica coerente com o respeito à diversidade é", "gabarito": "E", "comentario": "A diversidade é um valor e uma condição da aprendizagem, e não um problema a ser eliminado.", "alternativas": [["A", "exigir que todos os estudantes se comportem e pensem da mesma forma."], ["B", "ignorar os casos de discriminação para não expor os envolvidos."], ["C", "valorizar apenas a cultura da maioria."], ["D", "separar os estudantes por origem social."], ["E", "reconhecer e valorizar as diferentes culturas, histórias e formas de ser dos estudantes, combatendo toda forma de discriminação na escola."]]},
{"id": "AU-96c2debfab", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão da sala de aula", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A construção de combinados (acordos de convivência) com a turma, no início do ano, favorece a gestão da sala de aula porque", "gabarito": "D", "comentario": "Os combinados devem ser poucos, claros e retomados ao longo do ano.", "alternativas": [["A", "dispensa o professor de intervir nos conflitos."], ["B", "permite que cada estudante crie regras só para si."], ["C", "serve apenas para listar punições."], ["D", "envolve os estudantes na definição das regras, o que aumenta o sentido delas e a corresponsabilidade pelo seu cumprimento."], ["E", "transfere toda a responsabilidade pela disciplina para os estudantes."]]},
{"id": "AU-54d4f07c6a", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão da sala de aula", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na comunicação não violenta, proposta por Marshall Rosenberg, a expressão de uma situação de conflito envolve quatro componentes:", "gabarito": "B", "comentario": "Exemplo: \"Quando vejo papéis no chão (observação), fico chateado (sentimento), porque preciso da sala organizada para a aula (necessidade). Vocês podem recolhê-los? (pedido)\".", "alternativas": [["A", "silêncio, afastamento, advertência e suspensão."], ["B", "observação sem julgamento, sentimentos, necessidades e pedido."], ["C", "acusação, defesa, punição e perdão."], ["D", "ordem, ameaça, castigo e recompensa."], ["E", "diagnóstico, prescrição, cobrança e nota."]]},
{"id": "AU-642b73448f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Mediação de conflitos", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na mediação de conflitos escolares, o papel do mediador é", "gabarito": "E", "comentario": "Estudantes também podem ser formados como mediadores, o que fortalece a cultura de paz na escola.", "alternativas": [["A", "decidir quem está certo e aplicar a punição."], ["B", "tomar partido do estudante mais prejudicado."], ["C", "encerrar a conversa rapidamente com uma advertência."], ["D", "resolver o conflito sem ouvir os envolvidos."], ["E", "facilitar o diálogo entre as partes, de forma imparcial, para que elas mesmas construam uma solução."]]},
{"id": "AU-2efd6438d6", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Mediação de conflitos", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "As práticas restaurativas na escola, como os círculos de diálogo, buscam", "gabarito": "E", "comentario": "O foco sai da pergunta \"quem merece castigo?\" para \"quem foi afetado e como reparar?\".", "alternativas": [["A", "a punição exemplar, para servir de aviso aos demais."], ["B", "a exclusão definitiva de quem cometeu a falta."], ["C", "o silêncio sobre o ocorrido, para evitar exposição."], ["D", "a transferência de todos os envolvidos para outras escolas."], ["E", "a responsabilização de quem causou o dano, a reparação e a reconstrução das relações, com a participação dos envolvidos."]]},
{"id": "AU-7837fdc9ac", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão da sala de aula", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A disciplina positiva, aplicada à educação, propõe", "gabarito": "B", "comentario": "Limites claros e respeito mútuo caminham juntos.", "alternativas": [["A", "expor publicamente quem descumpre as regras."], ["B", "conduzir a turma com firmeza e gentileza ao mesmo tempo, focando em soluções e no ensino de habilidades sociais, sem humilhação."], ["C", "controlar o comportamento por meio de castigos e ameaças."], ["D", "deixar os estudantes sem nenhum limite."], ["E", "premiar apenas os estudantes mais quietos."]]},
{"id": "AU-23cbf07be0", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão da sala de aula", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Diante da indisciplina recorrente de uma turma, uma atitude pedagógica adequada é", "gabarito": "A", "comentario": "Aulas pouco desafiadoras ou confusas costumam favorecer a indisciplina; rever o planejamento faz parte da resposta.", "alternativas": [["A", "investigar as causas, que podem estar nas relações, na organização das aulas ou nas atividades propostas, e planejar intervenções educativas."], ["B", "atribuir o problema apenas às famílias e não fazer nada."], ["C", "aplicar a mesma punição coletiva a todos os estudantes."], ["D", "retirar os estudantes da sala até o fim do ano."], ["E", "ignorar o problema, para não perder tempo de aula."]]},
{"id": "AU-6b8da9b8ec", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão da sala de aula", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo a Lei n.º 13.185/2015, a intimidação sistemática (bullying) caracteriza-se por", "gabarito": "C", "comentario": "A lei prevê, entre outras ações, capacitar professores e equipes para a prevenção e o enfrentamento do problema.", "alternativas": [["A", "conflitos que ocorrem apenas fora da escola."], ["B", "desentendimentos entre professores."], ["C", "atos de violência física ou psicológica, intencionais e repetitivos, praticados sem motivação evidente, com desequilíbrio de poder entre as partes."], ["D", "qualquer discussão isolada entre dois estudantes."], ["E", "brincadeiras aceitas por todos os envolvidos."]]},
{"id": "AU-20c0fab091", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão da sala de aula", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na relação pedagógica, a autoridade do professor distingue-se do autoritarismo porque", "gabarito": "A", "comentario": "Paulo Freire defendia a autoridade democrática, que respeita a liberdade dos educandos sem cair na licenciosidade.", "alternativas": [["A", "se apoia na competência, no respeito e no diálogo, e não na imposição pelo medo."], ["B", "depende do volume da voz do professor."], ["C", "dispensa qualquer limite ou regra."], ["D", "se baseia na ameaça constante de reprovação."], ["E", "exige que os estudantes nunca façam perguntas."]]},
{"id": "AU-fd0d06ea45", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão da sala de aula", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Rotinas bem estabelecidas na sala de aula, como a forma de iniciar a aula e de fazer as transições entre atividades,", "gabarito": "A", "comentario": "Previsibilidade ajuda os estudantes a se organizarem, especialmente os que têm mais dificuldade de concentração.", "alternativas": [["A", "favorecem o uso do tempo para a aprendizagem e reduzem dispersões e conflitos."], ["B", "tornam a aula monótona e devem ser evitadas."], ["C", "impedem qualquer mudança no planejamento."], ["D", "servem apenas para a educação infantil."], ["E", "dispensam o planejamento das atividades."]]},
{"id": "AU-aaa81d6a93", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tecnologias na educação", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Ao planejar o uso de tecnologias digitais em uma aula, o professor deve partir", "gabarito": "A", "comentario": "A tecnologia é meio, não fim. Às vezes, a melhor escolha para o objetivo é um recurso simples.", "alternativas": [["A", "dos objetivos de aprendizagem, escolhendo o recurso que melhor contribui para alcançá-los."], ["B", "da ferramenta mais moderna, adaptando o conteúdo a ela."], ["C", "do que estiver disponível, sem relação com o conteúdo."], ["D", "da preferência dos estudantes por jogos."], ["E", "da obrigação de usar tecnologia em todas as aulas."]]},
{"id": "AU-f4d702b0e0", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tecnologias na educação", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A curadoria de conteúdos digitais pelo professor consiste em", "gabarito": "B", "comentario": "A curadoria também ensina pelo exemplo como checar fontes e escolher bem.", "alternativas": [["A", "copiar aulas prontas sem adaptação."], ["B", "selecionar, avaliar e organizar recursos confiáveis e adequados aos objetivos e à turma, contextualizando seu uso."], ["C", "repassar aos estudantes todos os links encontrados na internet."], ["D", "proibir o uso de qualquer conteúdo digital."], ["E", "comprar plataformas pagas para todas as disciplinas."]]},
{"id": "AU-10e561a281", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão democrática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O conselho escolar é um órgão colegiado que", "gabarito": "D", "comentario": "Pode ter funções deliberativas, consultivas, fiscais e mobilizadoras, conforme as normas de cada sistema.", "alternativas": [["A", "tem como única função organizar festas."], ["B", "decide sozinho as notas dos estudantes."], ["C", "substitui a secretaria de educação na gestão da rede."], ["D", "reúne representantes dos segmentos da comunidade escolar, como gestores, professores, funcionários, estudantes e famílias, e participa das decisões da escola."], ["E", "é formado apenas pelo diretor e pelo secretário escolar."]]},
{"id": "AU-4f95deb205", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão democrática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo a Lei n.º 7.398/1985, os estudantes dos estabelecimentos de ensino de 1º e 2º graus (atuais ensino fundamental e médio) têm assegurada a organização de", "gabarito": "D", "comentario": "O grêmio é espaço de participação e de formação para a cidadania.", "alternativas": [["A", "partidos políticos dentro da escola."], ["B", "conselhos tutelares escolares."], ["C", "associações comerciais."], ["D", "grêmios estudantis, como entidades autônomas representativas dos seus interesses."], ["E", "sindicatos profissionais."]]},
{"id": "AU-a96855df65", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão democrática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "No Programa Dinheiro Direto na Escola (PDDE), os recursos federais são repassados", "gabarito": "C", "comentario": "A gestão compartilhada dos recursos é uma expressão concreta da gestão democrática.", "alternativas": [["A", "apenas às escolas privadas."], ["B", "às prefeituras, para obras de pavimentação."], ["C", "às unidades executoras da escola, como associações de pais e mestres e caixas escolares, para manutenção e melhorias, com participação da comunidade na gestão e na prestação de contas."], ["D", "diretamente aos professores, como complemento salarial."], ["E", "às famílias dos estudantes, para compra de uniformes."]]},
{"id": "AU-a876ae7345", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão democrática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Uma relação de parceria entre escola e família caracteriza-se por", "gabarito": "E", "comentario": "A LDB incumbe as escolas de articular-se com as famílias e a comunidade e de informá-las sobre a frequência e o rendimento dos estudantes.", "alternativas": [["A", "transferir às famílias a responsabilidade de ensinar os conteúdos."], ["B", "contato com as famílias somente quando houver problemas de comportamento."], ["C", "impedir a presença das famílias na escola."], ["D", "decisões pedagógicas tomadas apenas pelas famílias."], ["E", "diálogo frequente sobre o desenvolvimento dos estudantes e participação das famílias na vida da escola, e não apenas convocações para reclamar."]]},
{"id": "AU-9f208cd131", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Gestão democrática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O regimento escolar é o documento que", "gabarito": "E", "comentario": "O regimento traduz em normas a organização prevista no projeto da escola.", "alternativas": [["A", "substitui o projeto político-pedagógico."], ["B", "contém apenas o calendário de provas."], ["C", "é igual ao plano de aula do professor."], ["D", "é elaborado pelos estudantes sem participação da escola."], ["E", "define a organização e o funcionamento da escola, incluindo direitos e deveres dos membros da comunidade escolar, em consonância com o PPP e as normas do sistema."]]},
{"id": "AU-63a55bbfe4", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Interdisciplinaridade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para Ivani Fazenda, a interdisciplinaridade é, sobretudo,", "gabarito": "E", "comentario": "A interdisciplinaridade exige trabalho coletivo e planejamento compartilhado.", "alternativas": [["A", "a eliminação das disciplinas escolares."], ["B", "a soma de conteúdos de várias disciplinas em uma mesma prova."], ["C", "um método rígido aplicado da mesma forma em todas as escolas."], ["D", "a substituição do professor especialista pelo generalista."], ["E", "uma atitude de abertura, parceria e diálogo entre os conhecimentos e entre os professores."]]},
{"id": "AU-b99095ca4d", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Interdisciplinaridade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Sobre multidisciplinaridade, interdisciplinaridade e transdisciplinaridade, é correto afirmar que", "gabarito": "C", "comentario": "A diferença está no grau de integração entre os saberes.", "alternativas": [["A", "a transdisciplinaridade exige que cada disciplina trabalhe isolada."], ["B", "a multidisciplinaridade elimina as disciplinas."], ["C", "na multidisciplinaridade as disciplinas apenas se justapõem em torno de um tema; na interdisciplinaridade elas interagem e se integram; na transdisciplinaridade o conhecimento ultrapassa as fronteiras disciplinares."], ["D", "os três termos têm exatamente o mesmo significado."], ["E", "a interdisciplinaridade é a simples justaposição de disciplinas."]]},
{"id": "AU-cd719831c1", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Interdisciplinaridade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Um projeto sobre a água no bairro, em que os estudantes analisam a qualidade da água em Ciências, calculam o consumo em Matemática, estudam a bacia hidrográfica em Geografia e produzem uma campanha em Língua Portuguesa, é exemplo de", "gabarito": "C", "comentario": "Problemas reais costumam exigir conhecimentos de várias áreas, o que favorece a integração.", "alternativas": [["A", "educação a distância."], ["B", "avaliação somativa."], ["C", "prática interdisciplinar, em que diferentes componentes se articulam em torno de um problema comum."], ["D", "ensino tradicional, centrado na memorização."], ["E", "trabalho isolado de cada disciplina, sem relação entre elas."]]},
{"id": "AU-1853b52dc1", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Interdisciplinaridade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A contextualização dos conteúdos, recomendada pelas diretrizes curriculares, consiste em", "gabarito": "B", "comentario": "Contextualizar não é empobrecer o conteúdo, e sim partir do contexto para chegar ao conhecimento sistematizado.", "alternativas": [["A", "substituir o currículo por conversas informais."], ["B", "relacionar os conhecimentos escolares às experiências, à realidade e às questões da vida dos estudantes, dando sentido ao que se aprende."], ["C", "reduzir o conteúdo ao que os estudantes já sabem."], ["D", "trabalhar apenas temas do cotidiano, sem conhecimento científico."], ["E", "apresentar os conteúdos sem relação com a realidade."]]},
{"id": "AU-026a4efcac", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Interdisciplinaridade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Os Parâmetros Curriculares Nacionais (PCN), de 1997, propuseram temas transversais a serem trabalhados ao longo de todas as áreas, como", "gabarito": "A", "comentario": "A ideia de transversalidade foi retomada na BNCC pelos Temas Contemporâneos Transversais.", "alternativas": [["A", "ética, saúde, meio ambiente, pluralidade cultural, orientação sexual e trabalho e consumo."], ["B", "álgebra, geometria e estatística."], ["C", "gramática, literatura e redação."], ["D", "física, química e biologia."], ["E", "inglês, espanhol e francês."]]},
{"id": "AU-605527ccb0", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Organização escolar", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo a LDB, a educação básica poderá organizar-se em", "gabarito": "A", "comentario": "É o art. 23 da LDB, que dá flexibilidade aos sistemas de ensino.", "alternativas": [["A", "séries anuais, períodos semestrais, ciclos, alternância regular de períodos de estudos, grupos não seriados ou outra forma diversa, sempre que o interesse do processo de aprendizagem assim o recomendar."], ["B", "apenas séries anuais, obrigatoriamente."], ["C", "somente ciclos de dois anos."], ["D", "turmas separadas por desempenho, exclusivamente."], ["E", "módulos a distância, obrigatoriamente."]]},
{"id": "AU-882946e6f3", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Organização escolar", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Pela LDB, a classificação do estudante em qualquer série ou etapa, exceto a primeira do ensino fundamental, pode ser feita", "gabarito": "A", "comentario": "É o art. 24, II. A regra permite matricular estudantes sem documentação escolar, após avaliação.", "alternativas": [["A", "por promoção, por transferência ou, independentemente de escolarização anterior, mediante avaliação feita pela escola."], ["B", "apenas por idade, sem nenhuma avaliação."], ["C", "somente por indicação da família."], ["D", "exclusivamente por transferência de outra escola."], ["E", "apenas por sorteio de vagas."]]},
{"id": "AU-8e773bbc8f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Organização escolar", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Entre as regras de verificação do rendimento escolar previstas na LDB, está a", "gabarito": "B", "comentario": "O art. 24, V, também prevê aceleração de estudos para estudantes com atraso escolar e aproveitamento de estudos concluídos.", "alternativas": [["A", "proibição do aproveitamento de estudos concluídos com êxito."], ["B", "possibilidade de avanço nos cursos e nas séries mediante verificação do aprendizado."], ["C", "proibição de qualquer forma de avanço antes do fim do ano."], ["D", "reprovação automática de quem falta a uma prova."], ["E", "obrigatoriedade de prova final em todas as séries."]]},
{"id": "AU-3f6d401569", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Fundamentos da educação", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A experiência de alfabetização de adultos em Angicos (RN), em 1963, ficou conhecida por", "gabarito": "C", "comentario": "As palavras geradoras, como \"tijolo\", eram discutidas nos círculos de cultura e depois decompostas em famílias silábicas.", "alternativas": [["A", "basear-se na memorização do alfabeto e de sílabas isoladas."], ["B", "ser realizada exclusivamente por meio do rádio."], ["C", "aplicar o método de Paulo Freire, partindo de palavras geradoras do universo dos trabalhadores e alfabetizando-os em poucas semanas."], ["D", "usar cartilhas importadas, sem relação com a realidade local."], ["E", "alfabetizar apenas crianças em idade escolar."]]},
{"id": "AU-78df87fb93", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Fundamentos da educação", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "As teorias chamadas crítico-reprodutivistas, como a de Bourdieu e Passeron, sustentam que", "gabarito": "B", "comentario": "A crítica alertou para mecanismos de exclusão; outras correntes, como a histórico-crítica, enfatizaram o potencial transformador da escola.", "alternativas": [["A", "as diferenças culturais não influenciam a aprendizagem."], ["B", "a escola tende a reproduzir as desigualdades sociais, ao valorizar o capital cultural das classes dominantes."], ["C", "a escola é sempre um instrumento de igualdade social."], ["D", "o desempenho escolar depende apenas do esforço individual."], ["E", "a escola é neutra e não tem relação com a sociedade."]]},
{"id": "AU-7d414ae4e5", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Fundamentos da educação", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A educação integral, presente em documentos como a BNCC, refere-se", "gabarito": "B", "comentario": "A jornada ampliada pode favorecer a educação integral, mas os conceitos não são iguais.", "alternativas": [["A", "à formação apenas para o trabalho."], ["B", "à formação e ao desenvolvimento humano global, nas dimensões intelectual, física, afetiva, social e cultural, e não apenas à ampliação da jornada escolar."], ["C", "apenas ao aumento do número de horas na escola."], ["D", "ao ensino exclusivo de conteúdos acadêmicos."], ["E", "à substituição da família pela escola."]]},
{"id": "AU-e616d939ec", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Didática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Antoni Zabala e César Coll classificam os conteúdos de aprendizagem em três tipos:", "gabarito": "C", "comentario": "Saber o que é fotossíntese é conceitual; montar um experimento é procedimental; respeitar o meio ambiente é atitudinal.", "alternativas": [["A", "obrigatórios, complementares e extracurriculares."], ["B", "orais, escritos e digitais."], ["C", "conceituais (fatos e conceitos), procedimentais (saber fazer) e atitudinais (valores, normas e atitudes)."], ["D", "teóricos, práticos e opcionais."], ["E", "fáceis, médios e difíceis."]]},
{"id": "AU-ceaa997f9a", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Didática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para Philippe Perrenoud, competência é", "gabarito": "A", "comentario": "Perrenoud também defende a pedagogia diferenciada, que ajusta as situações de aprendizagem às necessidades de cada estudante.", "alternativas": [["A", "a capacidade de mobilizar diversos recursos cognitivos, como saberes, habilidades e informações, para enfrentar um tipo de situação."], ["B", "a acumulação de conteúdos memorizados ao longo da escolaridade."], ["C", "uma aptidão inata, que não pode ser desenvolvida."], ["D", "o resultado de uma prova padronizada."], ["E", "a obediência às normas da escola."]]},
{"id": "AU-66ed136c71", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Didática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A pedagogia diferenciada propõe", "gabarito": "E", "comentario": "Agrupamentos flexíveis, tarefas com níveis de desafio diferentes e tutoria entre pares são exemplos.", "alternativas": [["A", "separar os estudantes em escolas diferentes conforme o desempenho."], ["B", "dar exatamente a mesma atividade a todos, no mesmo tempo."], ["C", "reduzir o conteúdo para os estudantes com dificuldade, sem nova estratégia."], ["D", "eliminar a avaliação."], ["E", "organizar situações de aprendizagem variadas, ajustadas aos diferentes níveis e necessidades dos estudantes de uma mesma turma."]]},
{"id": "AU-cc9cf56b11", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Didática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Ao iniciar uma aula, uma estratégia que favorece a aprendizagem é", "gabarito": "E", "comentario": "Saber aonde se quer chegar e ligar o novo ao que já se sabe dá sentido à aula.", "alternativas": [["A", "começar a matéria nova sem nenhuma conexão com as aulas anteriores."], ["B", "aplicar uma prova surpresa sobre o conteúdo que ainda será ensinado."], ["C", "omitir os objetivos, para manter o suspense."], ["D", "pedir silêncio absoluto durante toda a aula."], ["E", "retomar os conhecimentos prévios dos estudantes e deixar claros os objetivos da aula."]]},
{"id": "AU-7591c7b36a", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Didática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "No uso de perguntas em sala de aula, as perguntas abertas, como \"Por que você acha que isso aconteceu?\",", "gabarito": "B", "comentario": "Dar tempo para pensar antes de pedir a resposta também melhora a qualidade das participações.", "alternativas": [["A", "dispensam a escuta do professor."], ["B", "estimulam o raciocínio, a explicação e o levantamento de hipóteses, mais do que as perguntas que pedem apenas \"sim\" ou \"não\"."], ["C", "devem ser evitadas, porque confundem os estudantes."], ["D", "servem apenas para avaliar a memorização."], ["E", "só podem ser usadas no ensino médio."]]},
{"id": "AU-ce3d6fd7f4", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Didática", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Sobre a motivação para aprender, é correto afirmar que a motivação intrínseca", "gabarito": "C", "comentario": "Atividades com sentido, desafios adequados e autonomia favorecem a motivação intrínseca.", "alternativas": [["A", "não tem relação com o sentido das atividades."], ["B", "é igual em todos os estudantes e não pode ser estimulada."], ["C", "vem do interesse e da satisfação com a própria atividade, e tende a sustentar a aprendizagem por mais tempo."], ["D", "depende sempre de prêmios e notas."], ["E", "é provocada exclusivamente por punições."]]},
{"id": "AU-7003b14746", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Segundo Lawrence Kohlberg, o desenvolvimento moral passa por três níveis:", "gabarito": "D", "comentario": "Piaget também estudou o julgamento moral, descrevendo a passagem da heteronomia (regras impostas) para a autonomia.", "alternativas": [["A", "oral, anal e fálico."], ["B", "real, potencial e proximal."], ["C", "concreto, abstrato e simbólico."], ["D", "pré-convencional, convencional e pós-convencional."], ["E", "sensório-motor, pré-operatório e formal."]]},
{"id": "AU-0485f9f7b6", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Teorias da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A teoria da aprendizagem social, de Albert Bandura, destaca", "gabarito": "A", "comentario": "Por isso, o exemplo do professor também ensina.", "alternativas": [["A", "a aprendizagem por observação de modelos, como pais, professores e colegas."], ["B", "a aprendizagem apenas por tentativa e erro individual."], ["C", "a maturação biológica como única causa do desenvolvimento."], ["D", "os estágios do desenvolvimento cognitivo."], ["E", "as inteligências múltiplas."]]},
{"id": "AU-5a8feb0047", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Célestin Freinet propôs técnicas pedagógicas como", "gabarito": "E", "comentario": "Para Freinet, a escola deve partir da vida e do trabalho cooperativo dos estudantes.", "alternativas": [["A", "a instrução programada e as máquinas de ensinar."], ["B", "a palmatória e a memorização coletiva."], ["C", "os testes de inteligência e a classificação dos estudantes."], ["D", "a educação bancária e o ditado diário."], ["E", "a aula-passeio, o texto livre, o jornal escolar e a correspondência entre escolas."]]},
{"id": "AU-44af35023b", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Tendências pedagógicas", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "O método Montessori caracteriza-se, entre outros aspectos, por", "gabarito": "C", "comentario": "Maria Montessori via o professor como observador e orientador do desenvolvimento da criança.", "alternativas": [["A", "a aprendizagem centrada na memorização de regras."], ["B", "a ausência de organização do espaço."], ["C", "um ambiente preparado, com materiais concretos e autocorretivos, que favorece a autonomia e a atividade da criança."], ["D", "aulas expositivas longas e disciplina rígida."], ["E", "a proibição de materiais concretos."]]},
{"id": "AU-4dc94c2502", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Formação docente", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para Maurice Tardif, os saberes docentes são plurais e incluem, entre outros,", "gabarito": "D", "comentario": "Os saberes experienciais são construídos na prática e validados por ela.", "alternativas": [["A", "somente as técnicas de controle da turma."], ["B", "exclusivamente os saberes da experiência, sem teoria."], ["C", "apenas as normas do sistema de ensino."], ["D", "saberes da formação profissional, disciplinares, curriculares e experienciais."], ["E", "apenas os conteúdos aprendidos na graduação."]]},
{"id": "AU-e1d9c2004f", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Formação docente", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A ideia de professor reflexivo, associada a Donald Schön, destaca", "gabarito": "A", "comentario": "Registrar e discutir a prática com os colegas fortalece a formação em serviço.", "alternativas": [["A", "a reflexão na ação e sobre a ação como forma de o professor aprender com a própria prática."], ["B", "a aplicação de técnicas prontas, sem análise da realidade."], ["C", "a obediência a manuais sem adaptação."], ["D", "o trabalho isolado, sem troca com colegas."], ["E", "a dispensa da formação continuada."]]},
{"id": "AU-26b6556a18", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Avaliação da aprendizagem", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Os resultados das avaliações externas, como o Saeb, podem ser usados pedagogicamente pela escola para", "gabarito": "A", "comentario": "As escalas de proficiência mostram o que os estudantes de cada nível conseguem fazer.", "alternativas": [["A", "identificar habilidades em que os estudantes têm mais dificuldade e planejar intervenções."], ["B", "classificar os professores para punições."], ["C", "substituir a avaliação feita em sala de aula."], ["D", "reprovar os estudantes com baixo desempenho."], ["E", "escolher quais estudantes podem se matricular."]]},
{"id": "AU-b7b4c5a084", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Ao receber um estudante surdo usuário de Libras, a escola deve garantir, de acordo com a legislação,", "gabarito": "C", "comentario": "O Decreto n.º 5.626/2005 regulamenta a Libras e a formação de intérpretes e professores. A LDB prevê a educação bilíngue de surdos.", "alternativas": [["A", "apenas a leitura labial, sem Libras."], ["B", "a dispensa do estudante das avaliações."], ["C", "a presença de tradutor e intérprete de Libras e o ensino da língua portuguesa escrita como segunda língua."], ["D", "a proibição do uso de Libras em sala de aula."], ["E", "a transferência obrigatória para uma escola especial."]]},
{"id": "AU-8a096299c6", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Educação inclusiva", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Para estudantes cegos, são recursos de acessibilidade usados na escola:", "gabarito": "B", "comentario": "Estudantes com baixa visão podem precisar de ampliação, contraste e iluminação adequada.", "alternativas": [["A", "nenhum recurso específico, apenas a sala comum."], ["B", "o sistema Braille, o soroban para cálculos, materiais em alto-relevo e os leitores de tela."], ["C", "apenas imagens coloridas e projeções."], ["D", "somente provas orais, sem nenhum material."], ["E", "lupas eletrônicas para estudantes surdos."]]},
{"id": "AU-49acd31aa9", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diversidade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na educação do campo, a pedagogia da alternância caracteriza-se por", "gabarito": "B", "comentario": "As diretrizes da educação do campo pedem adequação do calendário e do currículo à realidade do campo.", "alternativas": [["A", "eliminar as aulas presenciais."], ["B", "alternar períodos na escola (tempo escola) e na comunidade e na propriedade familiar (tempo comunidade), integrando estudo e trabalho."], ["C", "proibir o estudante de trabalhar com a família."], ["D", "transferir os estudantes do campo para escolas urbanas."], ["E", "usar o mesmo calendário e currículo das escolas urbanas, sem adaptação."]]},
{"id": "AU-7caf59d95e", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diversidade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "A educação escolar quilombola e a educação escolar indígena, segundo as diretrizes nacionais, devem", "gabarito": "E", "comentario": "São modalidades da educação básica, com diretrizes próprias do Conselho Nacional de Educação.", "alternativas": [["A", "seguir exatamente o currículo das escolas urbanas, sem adaptação."], ["B", "proibir o uso das línguas e das tradições locais."], ["C", "ser oferecidas apenas no ensino superior."], ["D", "dispensar professores das próprias comunidades."], ["E", "considerar a cultura, a história, a língua e os saberes das comunidades, com participação delas na construção do currículo."]]},
{"id": "AU-33390c0bc0", "tipo": "me", "grupo": "especifica", "materia": "Conhecimentos pedagógicos", "origem": "Questão inédita · Diversidade", "fonte": "inedita", "texto": null, "comando": null, "enunciado": "Na educação de jovens e adultos, uma prática pedagógica coerente com o perfil dos estudantes é", "gabarito": "D", "comentario": "Paulo Freire desenvolveu seu trabalho principalmente com a alfabetização de adultos.", "alternativas": [["A", "desconsiderar a experiência dos estudantes, por ser informal."], ["B", "exigir a mesma rotina das crianças do ensino fundamental regular."], ["C", "ensinar apenas a assinar o nome."], ["D", "partir das experiências de vida e de trabalho dos estudantes, valorizando seus saberes e relacionando-os aos conteúdos."], ["E", "usar os mesmos materiais e exemplos da educação infantil."]]}
];
// uma cópia por área, com o id terminado na área
var AREAS = ["ciencias", "educacao-fisica", "pedagogia", "geografia", "historia", "ingles", "portugues", "matematica", "artes", "ensino-religioso"];
var copias = [];
questoes.forEach(function (q) {
  AREAS.forEach(function (a) {
    var c = {};
    Object.keys(q).forEach(function (k) { c[k] = q[k]; });
    c.id = q.id + '-' + a; c.area = a;
    copias.push(c);
  });
});
questoes = copias;
registrarPacote({ id: "ineditas-pedagogicos-igeduc", textos: {}, questoes: questoes });
})();
